#!/usr/bin/env bash
set -euo pipefail
DEST="${ECC_DEST:-$HOME/vhdl_repo/IP_Cores/ECC_Scrubber}"
mkdir -p "$DEST"
echo ">> destino: $DEST"
echo "" | base64 -d > "$DEST/ecc_selftest.c"
echo "" | base64 -d > "$DEST/ecc_fw_tiles.s"
echo "" | base64 -d > "$DEST/ecc_fw_selfcheck.s"
echo "" | base64 -d > "$DEST/tiles_oracle.py"
echo "" | base64 -d > "$DEST/ecc_regbank_si.vhd"
echo "" | base64 -d > "$DEST/tb_selfcheck_si.vhd"
echo "" | base64 -d > "$DEST/LAYER5_SILICON_PLAN.md"
ASM="${ASM:-$HOME/rv32i/asm.py}"; [ -f "$ASM" ] || ASM="$DEST/asm.py"
echo ">> compilando ecc-selftest (aarch64 si hay cross, si no gcc nativo para validar)"
if command -v aarch64-linux-gnu-gcc >/dev/null; then
  ( cd "$DEST" && aarch64-linux-gnu-gcc -O2 -static ecc_selftest.c -o ecc-selftest && echo "   ecc-selftest compilado (aarch64 estatico)" )
else
  ( cd "$DEST" && gcc -O2 -Wall -c ecc_selftest.c -o /tmp/ecc_st.o && echo "   ecc_selftest.c valida sintaxis con gcc nativo (falta cross aarch64)" )
fi
echo ">> ensamblando firmware de tiles"
( cd "$DEST" && python3 "$ASM" ecc_fw_tiles.s ecc_fw_tiles.mem >/dev/null && echo "   $(wc -l < ecc_fw_tiles.mem) instr" )
echo ">> oraculo de tiles"
( cd "$DEST" && python3 tiles_oracle.py | tail -3 )
echo ">> selfcheck codec sobre SoC real (prueba de vida)"
( cd "$DEST" && python3 "$ASM" ecc_fw_selfcheck.s ecc_fw_selfcheck.mem >/dev/null && rm -rf work-obj08.cf && \
  ghdl -a --std=08 riscv_pkg.vhd alu.vhd control.vhd immgen.vhd regfile.vhd csr.vhd muldiv.vhd \
    cpu_pipeline.vhd dp_ram.vhd dma_burst.vhd mem_subsys_dma.vhd axil_soc.vhd ecc_pkg.vhd ecc_codec.vhd \
    ecc_codec_mmio.vhd scrub_bram.vhd scrub_fsm.vhd ecc_regbank_si.vhd ecc_soc_si.vhd tb_selfcheck_si.vhd 2>/dev/null && \
  ghdl -r --std=08 tb_selfcheck_si --stop-time=10us 2>&1 | grep -oE "selfcheck fin: irq='[01]'" )
